import { useState, useMemo, useCallback, useEffect } from 'react'
import {
  cryptoData, trendingData, predictionMarketsData, mostVisitedData, newListingsData,
  formatPrice, formatLargeNumber, formatSupply,
  type CryptoAsset,
} from './data.ts'

// ─── Sparkline SVG ─────────────────────────────────────────────
function Sparkline({ data, positive }: { data: number[]; positive: boolean }) {
  const w = 120, h = 36, pad = 2
  const min = Math.min(...data), max = Math.max(...data)
  const range = max - min || 1
  const pts = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * (w - pad * 2)
    const y = h - pad - ((v - min) / range) * (h - pad * 2)
    return `${x},${y}`
  }).join(' ')
  const color = positive ? '#16c784' : '#ea3943'
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} className="block">
      <defs>
        <linearGradient id={`sg-${positive ? 'g' : 'r'}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.2" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <polygon
        points={`${pts} ${w - pad},${h} ${pad},${h}`}
        fill={`url(#sg-${positive ? 'g' : 'r'})`}
      />
      <polyline points={pts} fill="none" stroke={color} strokeWidth="1.5" strokeLinejoin="round" />
    </svg>
  )
}

// ─── Percent badge ─────────────────────────────────────────────
function PctBadge({ value, className = '' }: { value: number; className?: string }) {
  const pos = value >= 0
  return (
    <span className={`inline-flex items-center gap-0.5 tabular-nums text-xs font-medium ${pos ? 'text-green' : 'text-red'} ${className}`}>
      <svg width="8" height="8" viewBox="0 0 8 8" className={pos ? '' : 'rotate-180'}>
        <path d="M4 1L7 5H1L4 1Z" fill="currentColor" />
      </svg>
      {Math.abs(value).toFixed(2)}%
    </span>
  )
}

// ─── Star button for watchlist ─────────────────────────────────
function StarBtn({ active, onClick }: { active: boolean; onClick: () => void }) {
  return (
    <button onClick={onClick} className="text-gray-300 hover:text-yellow-400 transition-colors" aria-label="Toggle watchlist">
      <svg width="14" height="14" viewBox="0 0 24 24" fill={active ? '#f59e0b' : 'none'} stroke={active ? '#f59e0b' : 'currentColor'} strokeWidth="2">
        <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
      </svg>
    </button>
  )
}

// ─── Header / Navigation ───────────────────────────────────────
function Header() {
  const [menuOpen, setMenuOpen] = useState(false)
  const navItems = [
    { label: 'Cryptocurrencies', subs: ['Ranking', 'Categories', 'Historical Snapshots', 'Token Unlocks', 'Yield', 'Real-World Assets'] },
    { label: 'Dashboards', subs: ['Markets', 'Market Overview', 'Spot Market', 'Bitcoin Treasuries', 'Exchange Inflows/Outflows'] },
    { label: 'Exchanges', subs: ['Centralized', 'Decentralized', 'Spot', 'Derivatives'] },
    { label: 'DexScan', subs: ['Trending', 'New', 'Gainers', 'Meme Explorer', 'Top Traders'] },
    { label: 'More', subs: ['Portfolio', 'Watchlist'] },
  ]

  return (
    <header className="sticky top-0 z-50 bg-white border-b border-border">
      <div className="max-w-[1440px] mx-auto px-4 flex items-center h-14 justify-between">
        <div className="flex items-center gap-6">
          <a href="#" className="flex items-center gap-2 font-bold text-lg text-navy shrink-0">
            <div className="w-7 h-7 rounded-full bg-brand flex items-center justify-center">
              <span className="text-white text-sm font-extrabold">C</span>
            </div>
            CoinTracker<span className="text-brand">Pro</span>
          </a>
          <nav className="hidden lg:flex items-center gap-1">
            {navItems.map(item => (
              <div key={item.label} className="relative group">
                <button className="px-3 py-2 text-sm font-medium text-gray-sec hover:text-navy transition-colors flex items-center gap-1">
                  {item.label}
                  <svg width="10" height="10" viewBox="0 0 10 10" className="opacity-50"><path d="M2 4l3 3 3-3" fill="none" stroke="currentColor" strokeWidth="1.5" /></svg>
                </button>
                <div className="absolute top-full left-0 pt-1 hidden group-hover:block z-50">
                  <div className="bg-white border border-border rounded-lg shadow-lg py-1 min-w-[180px]">
                    {item.subs.map(s => (
                      <a key={s} href="#" className="block px-4 py-2 text-sm text-gray-600 hover:bg-surface hover:text-navy transition-colors">{s}</a>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </nav>
        </div>
        <div className="flex items-center gap-3">
          <div className="hidden md:flex items-center gap-2 bg-surface rounded-lg px-3 py-1.5">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#808A9D" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="M21 21l-4.35-4.35" /></svg>
            <input type="text" placeholder="Search..." className="bg-transparent text-sm outline-none w-36 text-navy placeholder:text-gray-sec" />
          </div>
          <button className="text-sm font-semibold text-gray-sec hover:text-navy transition-colors">Log In</button>
          <button className="text-sm font-semibold bg-brand text-white px-4 py-1.5 rounded-lg hover:bg-brand-light transition-colors">Sign Up</button>
          <button className="lg:hidden" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle menu">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 12h18M3 6h18M3 18h18" /></svg>
          </button>
        </div>
      </div>
      {menuOpen && (
        <div className="lg:hidden border-t border-border bg-white">
          {navItems.map(item => (
            <div key={item.label} className="border-b border-border-light">
              <div className="px-4 py-3 font-medium text-sm text-navy">{item.label}</div>
              <div className="px-6 pb-3 flex flex-wrap gap-2">
                {item.subs.map(s => <a key={s} href="#" className="text-xs text-gray-sec hover:text-brand">{s}</a>)}
              </div>
            </div>
          ))}
        </div>
      )}
    </header>
  )
}

// ─── Promotional Banner Carousel ───────────────────────────────
function PromoBanner() {
  const [idx, setIdx] = useState(0)
  const slides = [
    { text: 'CTP Launch: Secure $GENIUS Airdrop — Join Now', bg: 'from-brand/10 to-blue-50' },
    { text: 'Featured: Top DeFi Protocols Yield Analysis — Explore', bg: 'from-green/10 to-emerald-50' },
    { text: 'New: Bitcoin Treasuries Dashboard Now Live — View', bg: 'from-amber-100/50 to-yellow-50' },
  ]
  useEffect(() => {
    const t = setInterval(() => setIdx(i => (i + 1) % slides.length), 5000)
    return () => clearInterval(t)
  }, [slides.length])

  return (
    <div className="max-w-[1440px] mx-auto px-4 mt-3">
      <div className="relative overflow-hidden rounded-xl bg-gradient-to-r border border-border/50" style={{ minHeight: 48 }}>
        <div className={`flex items-center justify-center gap-3 px-4 py-3 bg-gradient-to-r ${slides[idx].bg} transition-all duration-500`}>
          <span className="bg-brand text-white text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider">New</span>
          <span className="text-sm font-medium text-navy">{slides[idx].text}</span>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-brand"><path d="M5 12h14m-7-7l7 7-7 7" /></svg>
        </div>
        <div className="absolute bottom-1.5 left-1/2 -translate-x-1/2 flex gap-1.5">
          {slides.map((_, i) => (
            <button key={i} onClick={() => setIdx(i)} className={`w-1.5 h-1.5 rounded-full transition-colors ${i === idx ? 'bg-brand' : 'bg-gray-300'}`} />
          ))}
        </div>
      </div>
    </div>
  )
}

