// ─── Column config ─────────────────────────────────────────────
const ALL_COLUMNS = [
  { id: 'rank', label: '#', defaultVisible: true },
  { id: 'name', label: 'Name', defaultVisible: true },
  { id: 'price', label: 'Price', defaultVisible: true },
  { id: '1h', label: '1h %', defaultVisible: true },
  { id: '24h', label: '24h %', defaultVisible: true },
  { id: '7d', label: '7d %', defaultVisible: true },
  { id: 'marketCap', label: 'Market Cap', defaultVisible: true },
  { id: 'volume', label: 'Volume(24h)', defaultVisible: true },
  { id: 'supply', label: 'Circulating Supply', defaultVisible: true },
  { id: 'sparkline', label: 'Last 7 Days', defaultVisible: true },
] as const

type ColumnId = typeof ALL_COLUMNS[number]['id']

// ─── Main App ──────────────────────────────────────────────────
export default function App() {
  const [categoryTab, setCategoryTab] = useState('Top')
  const [networkTab, setNetworkTab] = useState('All Networks')
  const [page, setPage] = useState(1)
  const [watchlist, setWatchlist] = useState<Set<string>>(new Set())
  const [sortCol, setSortCol] = useState<string>('marketCap')
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc')
  const [showColumns, setShowColumns] = useState(false)
  const [showFilters, setShowFilters] = useState(false)
  const [visibleCols, setVisibleCols] = useState<Set<ColumnId>>(new Set(ALL_COLUMNS.filter(c => c.defaultVisible).map(c => c.id)))
  const [marketSummaryExpanded, setMarketSummaryExpanded] = useState(false)
  const [minMarketCap, setMinMarketCap] = useState('')
  const [maxPrice, setMaxPrice] = useState('')

  const categoryTabs = ['Top', 'Trending', 'Watchlist', 'Prediction Markets', 'Most Visited', 'New']
  const networkTabs = ['All Networks', 'BSC', 'Solana', 'Base', 'Ethereum']

  const toggleWatchlist = useCallback((symbol: string) => {
    setWatchlist(prev => {
      const next = new Set(prev)
      if (next.has(symbol)) next.delete(symbol)
      else next.add(symbol)
      return next
    })
  }, [])

  const baseData = useMemo(() => {
    switch (categoryTab) {
      case 'Trending': return trendingData
      case 'Watchlist': return cryptoData.filter(c => watchlist.has(c.symbol))
      case 'Prediction Markets': return predictionMarketsData
      case 'Most Visited': return mostVisitedData
      case 'New': return newListingsData
      default: return cryptoData
    }
  }, [categoryTab, watchlist])

  const filtered = useMemo(() => {
    let d = baseData
    if (networkTab !== 'All Networks') d = d.filter(c => c.network === networkTab)
    if (minMarketCap) {
      const min = parseFloat(minMarketCap) * 1e9
      d = d.filter(c => c.marketCap >= min)
    }
    if (maxPrice) {
      const max = parseFloat(maxPrice)
      d = d.filter(c => c.price <= max)
    }
    return d
  }, [baseData, networkTab, minMarketCap, maxPrice])

  const sorted = useMemo(() => {
    const d = [...filtered]
    d.sort((a, b) => {
      let va: number, vb: number
      switch (sortCol) {
        case 'rank': va = a.rank; vb = b.rank; break
        case 'price': va = a.price; vb = b.price; break
        case '1h': va = a.change1h; vb = b.change1h; break
        case '24h': va = a.change24h; vb = b.change24h; break
        case '7d': va = a.change7d; vb = b.change7d; break
        case 'volume': va = a.volume24h; vb = b.volume24h; break
        case 'supply': va = a.circulatingSupply; vb = b.circulatingSupply; break
        default: va = a.marketCap; vb = b.marketCap; break
      }
      return sortDir === 'desc' ? vb - va : va - vb
    })
    return d
  }, [filtered, sortCol, sortDir])

  const totalPages = Math.max(1, Math.ceil(sorted.length / 100))
  const pageData = sorted.slice((page - 1) * 100, page * 100)

  const handleSort = (col: string) => {
    if (sortCol === col) setSortDir(d => d === 'desc' ? 'asc' : 'desc')
    else { setSortCol(col); setSortDir('desc') }
  }

  const toggleCol = (id: ColumnId) => {
    setVisibleCols(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const SortHeader = ({ col, label, align = 'right' }: { col: string; label: string; align?: string }) => (
    <th
      className={`px-3 py-2.5 text-[11px] font-semibold text-gray-sec uppercase tracking-wide cursor-pointer hover:text-navy transition-colors select-none whitespace-nowrap ${align === 'left' ? 'text-left' : 'text-right'}`}
      onClick={() => handleSort(col)}
    >
      <span className="inline-flex items-center gap-1">
        {label}
        {sortCol === col && (
          <svg width="8" height="8" viewBox="0 0 8 8" className={sortDir === 'asc' ? 'rotate-180' : ''}>
            <path d="M4 6L1 2h6L4 6z" fill="currentColor" />
          </svg>
        )}
      </span>
    </th>
  )

  return (
    <div className="min-h-screen bg-white">
      <Header />
      <PromoBanner />
      <AIAlertsBar />
      <MarketStats />

      {/* Main content area */}
      <main className="max-w-[1440px] mx-auto px-4 mt-6">
        {/* Category Tabs */}
        <div className="flex items-center gap-1 border-b border-border overflow-x-auto scrollbar-hide">
          {categoryTabs.map(tab => (
            <button
              key={tab}
              onClick={() => { setCategoryTab(tab); setPage(1) }}
              className={`px-4 py-2.5 text-sm font-semibold whitespace-nowrap transition-colors relative ${
                categoryTab === tab
                  ? 'text-brand'
                  : 'text-gray-sec hover:text-navy'
              }`}
            >
              {tab}
              {categoryTab === tab && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-brand rounded-t" />}
            </button>
          ))}
          <button className="px-3 py-2.5 text-sm font-semibold text-gray-sec hover:text-navy">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1" /><circle cx="19" cy="12" r="1" /><circle cx="5" cy="12" r="1" /></svg>
          </button>
        </div>

        {/* Network Filter Tabs */}
        <div className="flex items-center gap-2 mt-4 overflow-x-auto scrollbar-hide">
          {networkTabs.map(tab => (
            <button
              key={tab}
              onClick={() => { setNetworkTab(tab); setPage(1) }}
              className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-all ${
                networkTab === tab
                  ? 'bg-brand text-white shadow-sm'
                  : 'bg-surface text-gray-sec hover:bg-surface-hover hover:text-navy'
              }`}
            >
              {tab}
            </button>
          ))}
          <button className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-surface text-gray-sec hover:bg-surface-hover">More</button>
        </div>

        {/* Index Tracker */}
        <div className="mt-4 bg-surface/50 border border-border-light rounded-xl px-4 py-2.5 flex items-center gap-6 overflow-x-auto scrollbar-hide">
          <div className="flex items-center gap-2">
            <div className="w-5 h-5 bg-brand/10 rounded flex items-center justify-center">
              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#3861FB" strokeWidth="2.5"><path d="M3 17l6-6 4 4 8-8" /><path d="M17 3h4v4" /></svg>
            </div>
            <span className="text-xs font-semibold text-navy">CoinTracker 20 Index</span>
            <span className="text-[10px] text-gray-sec">(DTFCTP20)</span>
          </div>
          <span className="text-sm font-bold text-navy tabular-nums">$154.29</span>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1"><span className="text-[10px] text-gray-sec">1h</span><PctBadge value={0.21} /></div>
            <div className="flex items-center gap-1"><span className="text-[10px] text-gray-sec">24h</span><PctBadge value={1.15} /></div>
            <div className="flex items-center gap-1"><span className="text-[10px] text-gray-sec">7d</span><PctBadge value={4.97} /></div>
          </div>
        </div>

        {/* Table Controls */}
        <div className="mt-4 flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-2">
            <span className="text-xs font-semibold text-gray-sec">Sort by:</span>
            <button onClick={() => handleSort('marketCap')} className={`text-xs font-semibold px-2.5 py-1 rounded-md transition-colors ${sortCol === 'marketCap' ? 'bg-brand text-white' : 'bg-surface text-gray-sec hover:text-navy'}`}>
              Market Cap {sortCol === 'marketCap' && (sortDir === 'desc' ? '▾' : '▴')}
            </button>
            <button onClick={() => handleSort('volume')} className={`text-xs font-semibold px-2.5 py-1 rounded-md transition-colors ${sortCol === 'volume' ? 'bg-brand text-white' : 'bg-surface text-gray-sec hover:text-navy'}`}>
              Volume(24h) {sortCol === 'volume' && (sortDir === 'desc' ? '▾' : '▴')}
            </button>
          </div>
          <div className="flex items-center gap-2">
            <div className="relative">
              <button
                onClick={() => { setShowFilters(!showFilters); setShowColumns(false) }}
                className={`text-xs font-semibold px-3 py-1.5 rounded-lg border transition-colors flex items-center gap-1.5 ${showFilters ? 'border-brand text-brand bg-brand/5' : 'border-border text-gray-sec hover:text-navy hover:border-gray-300'}`}
              >
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M22 3H2l8 9.46V19l4 2v-8.54L22 3z" /></svg>
                Filters
              </button>
              {showFilters && (
                <div className="absolute top-full right-0 mt-2 bg-white border border-border rounded-xl shadow-xl p-4 z-40 w-64 animate-fade-in-up">
                  <div className="text-xs font-semibold text-navy mb-3">Filter Criteria</div>
                  <div className="space-y-3">
                    <div>
                      <label className="text-[11px] font-medium text-gray-sec block mb-1">Min Market Cap ($B)</label>
                      <input type="number" value={minMarketCap} onChange={e => setMinMarketCap(e.target.value)} placeholder="e.g. 1" className="w-full text-xs border border-border rounded-lg px-3 py-1.5 outline-none focus:border-brand" />
                    </div>
                    <div>
                      <label className="text-[11px] font-medium text-gray-sec block mb-1">Max Price ($)</label>
                      <input type="number" value={maxPrice} onChange={e => setMaxPrice(e.target.value)} placeholder="e.g. 100" className="w-full text-xs border border-border rounded-lg px-3 py-1.5 outline-none focus:border-brand" />
                    </div>
                    <button onClick={() => { setMinMarketCap(''); setMaxPrice(''); setShowFilters(false) }} className="text-[11px] font-semibold text-brand hover:underline">Clear All</button>
                  </div>
                </div>
              )}
            </div>
            <div className="relative">
              <button
                onClick={() => { setShowColumns(!showColumns); setShowFilters(false) }}
                className={`text-xs font-semibold px-3 py-1.5 rounded-lg border transition-colors flex items-center gap-1.5 ${showColumns ? 'border-brand text-brand bg-brand/5' : 'border-border text-gray-sec hover:text-navy hover:border-gray-300'}`}
              >
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="3" width="7" height="7" /><rect x="14" y="3" width="7" height="7" /><rect x="14" y="14" width="7" height="7" /><rect x="3" y="14" width="7" height="7" /></svg>
                Columns
              </button>
              {showColumns && (
                <div className="absolute top-full right-0 mt-2 bg-white border border-border rounded-xl shadow-xl p-3 z-40 w-52 animate-fade-in-up">
                  <div className="text-xs font-semibold text-navy mb-2">Toggle Columns</div>
                  {ALL_COLUMNS.map(col => (
                    <label key={col.id} className="flex items-center gap-2 py-1 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={visibleCols.has(col.id)}
                        onChange={() => toggleCol(col.id)}
                        className="accent-brand w-3.5 h-3.5"
                      />
                      <span className="text-xs text-gray-600">{col.label}</span>
                    </label>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Crypto Rankings Table */}
        <div className="mt-3 overflow-x-auto border border-border rounded-xl">
          <table className="w-full min-w-[900px]">
            <thead className="bg-surface/80">
              <tr>
                <th className="w-8 px-2 py-2.5"></th>
                {visibleCols.has('rank') && <SortHeader col="rank" label="#" align="left" />}
                {visibleCols.has('name') && <th className="px-3 py-2.5 text-[11px] font-semibold text-gray-sec uppercase tracking-wide text-left">Name</th>}
                {visibleCols.has('price') && <SortHeader col="price" label="Price" />}
                {visibleCols.has('1h') && <SortHeader col="1h" label="1h %" />}
                {visibleCols.has('24h') && <SortHeader col="24h" label="24h %" />}
                {visibleCols.has('7d') && <SortHeader col="7d" label="7d %" />}
                {visibleCols.has('marketCap') && <SortHeader col="marketCap" label="Market Cap" />}
                {visibleCols.has('volume') && <SortHeader col="volume" label="Volume(24h)" />}
                {visibleCols.has('supply') && <SortHeader col="supply" label="Circulating Supply" />}
                {visibleCols.has('sparkline') && <th className="px-3 py-2.5 text-[11px] font-semibold text-gray-sec uppercase tracking-wide text-right">Last 7 Days</th>}
              </tr>
            </thead>
            <tbody>
              {pageData.length === 0 ? (
                <tr><td colSpan={11} className="text-center py-16 text-gray-sec text-sm">
                  {categoryTab === 'Watchlist' ? 'No items in your watchlist. Star some coins to add them.' : 'No results match your filters.'}
                </td></tr>
              ) : pageData.map((coin, i) => (
                <tr
                  key={coin.symbol + coin.rank}
                  className="border-t border-border-light hover:bg-surface/50 transition-colors group"
                  style={{ animationDelay: `${i * 10}ms` }}
                >
                  <td className="px-2 py-2.5 text-center">
                    <StarBtn active={watchlist.has(coin.symbol)} onClick={() => toggleWatchlist(coin.symbol)} />
                  </td>
                  {visibleCols.has('rank') && (
                    <td className="px-3 py-2.5 text-xs font-medium text-gray-sec">{coin.rank}</td>
                  )}
                  {visibleCols.has('name') && (
                    <td className="px-3 py-2.5">
                      <div className="flex items-center gap-2.5">
                        <div className="w-7 h-7 rounded-full bg-gradient-to-br from-brand/20 to-brand/5 flex items-center justify-center text-[10px] font-bold text-brand shrink-0">
                          {coin.symbol.slice(0, 2)}
                        </div>
                        <div>
                          <div className="text-sm font-semibold text-navy group-hover:text-brand transition-colors">{coin.name}</div>
                          <div className="text-[11px] text-gray-sec font-medium">{coin.symbol}</div>
                        </div>
                      </div>
                    </td>
                  )}
                  {visibleCols.has('price') && (
                    <td className="px-3 py-2.5 text-right text-sm font-semibold text-navy tabular-nums">{formatPrice(coin.price)}</td>
                  )}
                  {visibleCols.has('1h') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change1h} /></td>}
                  {visibleCols.has('24h') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change24h} /></td>}
                  {visibleCols.has('7d') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change7d} /></td>}
                  {visibleCols.has('marketCap') && (
                    <td className="px-3 py-2.5 text-right text-sm font-medium text-navy tabular-nums">{formatLargeNumber(coin.marketCap)}</td>
                  )}
                  {visibleCols.has('volume') && (
                    <td className="px-3 py-2.5 text-right text-sm font-medium text-navy tabular-nums">{formatLargeNumber(coin.volume24h)}</td>
                  )}
                  {visibleCols.has('supply') && (
                    <td className="px-3 py-2.5 text-right text-xs text-gray-sec tabular-nums">{formatSupply(coin.circulatingSupply, coin.supplySymbol)}</td>
                  )}
                  {visibleCols.has('sparkline') && (
                    <td className="px-3 py-2.5 text-right">
                      <div className="inline-block"><Sparkline data={coin.sparkline} positive={coin.change7d >= 0} /></div>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="mt-4 flex items-center justify-between flex-wrap gap-3 pb-2">
          <div className="text-xs text-gray-sec">
            Showing {((page - 1) * 100) + 1}–{Math.min(page * 100, sorted.length)} of {sorted.length.toLocaleString()} assets
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="w-8 h-8 rounded-lg border border-border text-gray-sec hover:border-brand hover:text-brand disabled:opacity-40 disabled:hover:border-border disabled:hover:text-gray-sec transition-colors flex items-center justify-center"
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M15 18l-6-6 6-6" /></svg>
            </button>
            {Array.from({ length: Math.min(totalPages, 4) }, (_, i) => i + 1).map(p => (
              <button
                key={p}
                onClick={() => setPage(p)}
                className={`w-8 h-8 rounded-lg text-xs font-semibold transition-colors ${
                  page === p ? 'bg-brand text-white' : 'border border-border text-gray-sec hover:border-brand hover:text-brand'
                }`}
              >
                {p}
              </button>
            ))}
            {totalPages > 4 && (
              <>
                <span className="text-gray-sec text-xs px-1">...</span>
                <button
                  onClick={() => setPage(84)}
                  className={`w-8 h-8 rounded-lg text-xs font-semibold border border-border text-gray-sec hover:border-brand hover:text-brand transition-colors`}
                >
                  84
                </button>
              </>
            )}
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="w-8 h-8 rounded-lg border border-border text-gray-sec hover:border-brand hover:text-brand disabled:opacity-40 disabled:hover:border-border disabled:hover:text-gray-sec transition-colors flex items-center justify-center"
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M9 18l6-6-6-6" /></svg>
            </button>
          </div>
        </div>

        {/* Market Summary */}
        <section className="mt-8 border-t border-border pt-6">
          <h2 className="text-lg font-bold text-navy mb-3">Market Summary</h2>
          <div className="text-sm text-gray-600 leading-relaxed">
            <p>
              The global crypto market cap is <strong className="text-navy">$2.56T</strong>, a <strong className="text-green">1.47% increase</strong> over the last day.
              The total crypto market volume over the last 24 hours is <strong className="text-navy">$156.9B</strong>, a <strong className="text-green">14.51% increase</strong>.
              The total volume in DeFi is currently $12.2B, 7.78% of the total crypto market 24-hour volume.
              The volume of all stablecoins is $195.53B, representing 124.63% of total 24-hour volume.
            </p>
            {!marketSummaryExpanded && (
              <button onClick={() => setMarketSummaryExpanded(true)} className="text-brand font-semibold text-sm mt-2 hover:underline flex items-center gap-1">
                Read More
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M6 9l6 6 6-6" /></svg>
              </button>
            )}
            {marketSummaryExpanded && (
