import { useState, useMemo, useCallback, useEffect } from 'react'
import {
  cryptoData, trendingData, predictionMarketsData, mostVisitedData, newListingsData,
  formatPrice, formatLargeNumber, formatSupply,
  type CryptoAsset,
} from './data.ts'

// ─── Sparkline SVG ─────────────────────────────────────────────
function Sparkline({ data, positive }: { data: number[]; positive: boolean }) {
  const w = 120, h = 36, pad = 2
  const min = Math.min(...data), max = Math.max(...data)
  const range = max - min || 1
  const pts = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * (w - pad * 2)
    const y = h - pad - ((v - min) / range) * (h - pad * 2)
    return `${x},${y}`
  }).join(' ')
  const color = positive ? '#16c784' : '#ea3943'
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} className="block">
      <defs>
        <linearGradient id={`sg-${positive ? 'g' : 'r'}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.2" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <polygon
        points={`${pts} ${w - pad},${h} ${pad},${h}`}
        fill={`url(#sg-${positive ? 'g' : 'r'})`}
      />
      <polyline points={pts} fill="none" stroke={color} strokeWidth="1.5" strokeLinejoin="round" />
    </svg>
  )
}

// ─── Percent badge ─────────────────────────────────────────────
function PctBadge({ value, className = '' }: { value: number; className?: string }) {
  const pos = value >= 0
  return (
    <span className={`inline-flex items-center gap-0.5 tabular-nums text-xs font-medium ${pos ? 'text-green' : 'text-red'} ${className}`}>
      <svg width="8" height="8" viewBox="0 0 8 8" className={pos ? '' : 'rotate-180'}>
        <path d="M4 1L7 5H1L4 1Z" fill="currentColor" />
      </svg>
      {Math.abs(value).toFixed(2)}%
    </span>
  )
}

// ─── Star button for watchlist ─────────────────────────────────
function StarBtn({ active, onClick }: { active: boolean; onClick: () => void }) {
  return (
    <button onClick={onClick} className="text-gray-300 hover:text-yellow-400 transition-colors" aria-label="Toggle watchlist">
      <svg width="14" height="14" viewBox="0 0 24 24" fill={active ? '#f59e0b' : 'none'} stroke={active ? '#f59e0b' : 'currentColor'} strokeWidth="2">
        <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
