                      <div className="flex items-center gap-2.5">
                        <div className="w-7 h-7 rounded-full bg-gradient-to-br from-brand/20 to-brand/5 flex items-center justify-center text-[10px] font-bold text-brand shrink-0">
                          {coin.symbol.slice(0, 2)}
                        </div>
                        <div>
                          <div className="text-sm font-semibold text-navy group-hover:text-brand transition-colors">{coin.name}</div>
                          <div className="text-[11px] text-gray-sec font-medium">{coin.symbol}</div>
                        </div>
                      </div>
                    </td>
                  )}
                  {visibleCols.has('price') && (
                    <td className="px-3 py-2.5 text-right text-sm font-semibold text-navy tabular-nums">{formatPrice(coin.price)}</td>
                  )}
                  {visibleCols.has('1h') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change1h} /></td>}
                  {visibleCols.has('24h') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change24h} /></td>}
                  {visibleCols.has('7d') && <td className="px-3 py-2.5 text-right"><PctBadge value={coin.change7d} /></td>}
                  {visibleCols.has('marketCap') && (
                    <td className="px-3 py-2.5 text-right text-sm font-medium text-navy tabular-nums">{formatLargeNumber(coin.marketCap)}</td>
                  )}
                  {visibleCols.has('volume') && (
                    <td className="px-3 py-2.5 text-right text-sm font-medium text-navy tabular-nums">{formatLargeNumber(coin.volume24h)}</td>
                  )}
                  {visibleCols.has('supply') && (
                    <td className="px-3 py-2.5 text-right text-xs text-gray-sec tabular-nums">{formatSupply(coin.circulatingSupply, coin.supplySymbol)}</td>
                  )}
                  {visibleCols.has('sparkline') && (
                    <td className="px-3 py-2.5 text-right">
                      <div className="inline-block"><Sparkline data={coin.sparkline} positive={coin.change7d >= 0} /></div>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="mt-4 flex items-center justify-between flex-wrap gap-3 pb-2">
          <div className="text-xs text-gray-sec">
            Showing {((page - 1) * 100) + 1}–{Math.min(page * 100, sorted.length)} of {sorted.length.toLocaleString()} assets
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="w-8 h-8 rounded-lg border border-border text-gray-sec hover:border-brand hover:text-brand disabled:opacity-40 disabled:hover:border-border disabled:hover:text-gray-sec transition-colors flex items-center justify-center"
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M15 18l-6-6 6-6" /></svg>
            </button>
            {Array.from({ length: Math.min(totalPages, 4) }, (_, i) => i + 1).map(p => (
              <button
                key={p}
                onClick={() => setPage(p)}
                className={`w-8 h-8 rounded-lg text-xs font-semibold transition-colors ${
                  page === p ? 'bg-brand text-white' : 'border border-border text-gray-sec hover:border-brand hover:text-brand'
                }`}
              >
                {p}
              </button>
            ))}
            {totalPages > 4 && (
              <>
                <span className="text-gray-sec text-xs px-1">...</span>
                <button
                  onClick={() => setPage(84)}
                  className={`w-8 h-8 rounded-lg text-xs font-semibold border border-border text-gray-sec hover:border-brand hover:text-brand transition-colors`}
                >
                  84
                </button>
              </>
            )}
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="w-8 h-8 rounded-lg border border-border text-gray-sec hover:border-brand hover:text-brand disabled:opacity-40 disabled:hover:border-border disabled:hover:text-gray-sec transition-colors flex items-center justify-center"
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M9 18l6-6-6-6" /></svg>
            </button>
          </div>
        </div>

        {/* Market Summary */}
        <section className="mt-8 border-t border-border pt-6">
          <h2 className="text-lg font-bold text-navy mb-3">Market Summary</h2>
          <div className="text-sm text-gray-600 leading-relaxed">
            <p>
              The global crypto market cap is <strong className="text-navy">$2.56T</strong>, a <strong className="text-green">1.47% increase</strong> over the last day.
              The total crypto market volume over the last 24 hours is <strong className="text-navy">$156.9B</strong>, a <strong className="text-green">14.51% increase</strong>.
              The total volume in DeFi is currently $12.2B, 7.78% of the total crypto market 24-hour volume.
              The volume of all stablecoins is $195.53B, representing 124.63% of total 24-hour volume.
            </p>
            {!marketSummaryExpanded && (
              <button onClick={() => setMarketSummaryExpanded(true)} className="text-brand font-semibold text-sm mt-2 hover:underline flex items-center gap-1">
                Read More
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M6 9l6 6 6-6" /></svg>
              </button>
            )}
            {marketSummaryExpanded && (
              <div className="mt-3 animate-fade-in-up">
                <p className="mt-2">
                  Bitcoin's dominance is currently <strong className="text-navy">59.04%</strong>, a decrease of 0.05% over the day.
                  Ethereum's market share stands at 11.10%, while other major altcoins collectively represent 29.86% of the total market.
                  Institutional flows continue to show strength with spot Bitcoin ETFs recording net positive inflows for the third consecutive week.
                </p>
                <p className="mt-2">
                  The DeFi sector has seen a resurgence with total value locked (TVL) across major protocols reaching $87.3B.
                  Layer 2 solutions on Ethereum have processed over 45M transactions in the past week, demonstrating continued growth in scaling solutions.
                </p>
                <button onClick={() => setMarketSummaryExpanded(false)} className="text-brand font-semibold text-sm mt-2 hover:underline flex items-center gap-1">
                  Show Less
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="rotate-180"><path d="M6 9l6 6 6-6" /></svg>
                </button>
              </div>
            )}
          </div>
        </section>

        {/* Info Content */}
        <section className="mt-10 border-t border-border pt-8 pb-12">
          <h2 className="text-xl font-bold text-navy mb-4">Today's Cryptocurrency Prices, Charts and Data</h2>
          <p className="text-sm text-gray-600 leading-relaxed mb-6">
            Welcome to CoinTracker Pro! Founded to provide up-to-date cryptocurrency prices, charts, and data about the emerging cryptocurrency markets. We take our data seriously and stand for accurate, timely, and unbiased information.
          </p>

          <div className="grid md:grid-cols-2 gap-6">
            <div className="bg-surface/50 rounded-xl p-5 border border-border-light">
              <h3 className="text-sm font-bold text-navy mb-2">All Your Crypto Market Data Needs in One Place</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                CoinTracker Pro ensures all relevant information about cryptocurrencies, coins, and tokens can be located in one easily discoverable place.
              </p>
            </div>
            <div className="bg-surface/50 rounded-xl p-5 border border-border-light">
              <h3 className="text-sm font-bold text-navy mb-2">Live and Historic Crypto Charts for Free</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                Each coin data page features graphs showing current and historic price information. Professional traders can access our API, enabling millions of calls to track current and historic prices.
              </p>
            </div>
            <div className="bg-surface/50 rounded-xl p-5 border border-border-light">
              <h3 className="text-sm font-bold text-navy mb-2">How Do We Calculate Cryptocurrency Prices?</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                We receive updated prices directly from exchanges based on their trading pairs, then convert to USD.
              </p>
            </div>
            <div className="bg-surface/50 rounded-xl p-5 border border-border-light">
              <h3 className="text-sm font-bold text-navy mb-2">How Do We Calculate Crypto Valuations?</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                Valuations are based on total circulating supply multiplied by the currency reference price.
              </p>
            </div>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="bg-navy text-white">
        <div className="max-w-[1440px] mx-auto px-4 py-12">
          <div className="grid grid-cols-2 md:grid-cols-5 gap-8">
            <div className="col-span-2 md:col-span-1">
              <div className="flex items-center gap-2 font-bold text-lg mb-4">
                <div className="w-7 h-7 rounded-full bg-brand flex items-center justify-center">
                  <span className="text-white text-sm font-extrabold">C</span>
                </div>
                CoinTracker<span className="text-brand-light">Pro</span>
              </div>
              <p className="text-xs text-gray-400 leading-relaxed">
                Providing accurate, timely, and unbiased crypto market intelligence since 2025.
              </p>
            </div>
            <div>
              <h4 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Products</h4>
              <div className="space-y-2">
                {['Cryptocurrencies', 'Exchanges', 'DexScan', 'Portfolio', 'Watchlist'].map(item => (
                  <a key={item} href="#" className="block text-sm text-gray-300 hover:text-white transition-colors">{item}</a>
                ))}
              </div>
            </div>
            <div>
              <h4 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Company</h4>
              <div className="space-y-2">
                {['About', 'Terms of Use', 'Privacy Policy', 'Methodology', 'Disclaimer'].map(item => (
                  <a key={item} href="#" className="block text-sm text-gray-300 hover:text-white transition-colors">{item}</a>
                ))}
              </div>
            </div>
            <div>
              <h4 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Support</h4>
              <div className="space-y-2">
                {['FAQ', 'Glossary', 'Crypto Learning Center', 'API Documentation'].map(item => (
                  <a key={item} href="#" className="block text-sm text-gray-300 hover:text-white transition-colors">{item}</a>
                ))}
              </div>
            </div>
            <div>
              <h4 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Community</h4>
              <div className="space-y-2">
                {['Twitter', 'Telegram', 'Discord', 'Instagram'].map(item => (
                  <a key={item} href="#" className="block text-sm text-gray-300 hover:text-white transition-colors">{item}</a>
                ))}
              </div>
            </div>
          </div>
          <div className="mt-10 pt-6 border-t border-white/10 text-center text-xs text-gray-500">
            &copy; 2025 CoinTracker Pro. All rights reserved.
          </div>
        </div>
      </footer>
    </div>
  )
}

